package io.tornado.reporting;

import io.tornado.persistence.Direction;
import io.tornado.persistence.MixTradeSimulation;
import io.tornado.persistence.MixTradeSimulationRepository;
import org.springframework.jdbc.core.namedparam.MapSqlParameterSource;
import org.springframework.jdbc.core.namedparam.NamedParameterJdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.time.Duration;
import java.time.Instant;
import java.util.*;

@Service
public class OpportunityAnalyticsService {
    private final NamedParameterJdbcTemplate jdbc;
    private final MixTradeSimulationRepository opportunities;
    private final FirstTouchOutcomeResolver outcomes;

    public OpportunityAnalyticsService(NamedParameterJdbcTemplate jdbc, MixTradeSimulationRepository opportunities, FirstTouchOutcomeResolver outcomes) {
        this.jdbc = jdbc; this.opportunities = opportunities; this.outcomes = outcomes;
    }

    public Dashboard dashboard(Filter filter) {
        Sql sql = sql(filter);
        Map<String,Object> summary = jdbc.queryForMap("SELECT count(*) total,"+
                count("s.eligible_for_notification")+" notification_eligible,"+count("NOT s.eligible_for_notification")+" notification_suppressed,"+count("s.telegram_sent")+" telegram_sent,"+
                count("("+sql.outcome+"='SUCCESS')")+" successful,"+count("("+sql.outcome+"='FAILED')")+" failed,"+count("("+sql.outcome+"='UNRESOLVED')")+" unresolved,"+count("("+sql.outcome+"='AMBIGUOUS')")+" ambiguous,"+
                "COALESCE(avg(s.historical_target_hit_rate),0) avg_historical_win_rate,COALESCE(avg(s.historical_directional_accuracy),0) avg_directional_accuracy,COALESCE(avg(s.historical_wilson_score),0) avg_wilson_score,COALESCE(avg(CAST(s.agreement_count AS DOUBLE PRECISION)/NULLIF(s.total_methods,0)),0) avg_agreement_ratio,"+
                count("s.tp1_hit_at IS NOT NULL")+" tp1_reached,"+count("s.tp2_hit_at IS NOT NULL")+" tp2_reached,"+count("s.tp3_hit_at IS NOT NULL")+" tp3_reached,"+count("s.sl1_hit_at IS NOT NULL")+" sl1_reached,"+count("s.sl2_hit_at IS NOT NULL")+" sl2_reached,"+count("s.sl3_hit_at IS NOT NULL")+" sl3_reached "+sql.fromWhere,sql.params);
        long success=number(summary,"successful"), failed=number(summary,"failed"), total=number(summary,"total"), resolved=success+failed;
        Summary metrics=new Summary(total,number(summary,"notification_eligible"),number(summary,"notification_suppressed"),number(summary,"telegram_sent"),number(summary,"unresolved"),resolved,success,failed,number(summary,"ambiguous"),percent(success,resolved),percent(failed,resolved),decimal(summary,"avg_historical_win_rate"),decimal(summary,"avg_directional_accuracy"),decimal(summary,"avg_wilson_score"),decimal(summary,"avg_agreement_ratio")*100,rate(summary,"tp1_reached",total),rate(summary,"tp2_reached",total),rate(summary,"tp3_reached",total),rate(summary,"sl1_reached",total),rate(summary,"sl2_reached",total),rate(summary,"sl3_reached",total));
        return new Dashboard(metrics,groupByDay(sql),groupByCoin(sql),groupByHorizon(sql),groupByMix(sql),buckets(sql),matrix(filter));
    }

    public Page list(Filter filter,int page,int size) {
        if(page<0)throw new IllegalArgumentException("page must be zero or greater");if(size<1||size>200)throw new IllegalArgumentException("size must be between 1 and 200");
        Sql sql=sql(filter);MapSqlParameterSource params=copy(sql.params).addValue("limit",size).addValue("offset",(long)page*size);
        String select="SELECT s.id,c.symbol,c.pair,s.direction,s.horizon_seconds,s.opened_at,s.entry_price,s.mix_rank,s.mix_size,s.method_names,s.historical_target_hit_rate,s.historical_wilson_score,s.ranking_tp_level,s.ranking_target_percent,s.tp"+filter.tpLevel()+"_percent selected_tp_percent,s.sl"+filter.slLevel()+"_percent selected_sl_percent,s.tp"+filter.tpLevel()+"_hit_at selected_tp_at,s.sl"+filter.slLevel()+"_hit_at selected_sl_at,s.eligible_for_notification,s.telegram_sent,s.notification_suppression_reason,s.status,"+sql.outcome+" outcome "+sql.fromWhere+" ORDER BY s.opened_at DESC,s.id DESC LIMIT :limit OFFSET :offset";
        List<Row> rows=jdbc.query(select,params,(rs,n)->row(rs));long total=jdbc.queryForObject("SELECT count(*) "+sql.fromWhere,sql.params,Long.class);
        return new Page(rows,page,size,total,(int)Math.ceil(total/(double)size));
    }

    @Transactional(readOnly=true)
    public Detail detail(long id,int tpLevel,int slLevel) {
        validateLevels(tpLevel,slLevel);MixTradeSimulation s=opportunities.findWithCoinById(id).orElseThrow();FirstTouchOutcomeResolver.Outcome selected=outcomes.resolve(s,tpLevel,slLevel);List<Milestone> timeline=new ArrayList<>();timeline.add(new Milestone("ENTRY",s.getOpenedAt(),null,s.getEntryPrice(),null));for(int i=1;i<=3;i++){if(s.tpHitAt(i)!=null)timeline.add(new Milestone("TP"+i,s.tpHitAt(i),s.tpHitSequence(i),s.tpPrice(i),s.tpPercent(i)));if(s.slHitAt(i)!=null)timeline.add(new Milestone("SL"+i,s.slHitAt(i),s.slHitSequence(i),s.slPrice(i),s.slPercent(i)));}timeline.sort(Comparator.comparing(Milestone::at).thenComparing(Milestone::sequence,Comparator.nullsLast(Long::compareTo)).thenComparing(Milestone::name));List<MatrixCell> matrix=new ArrayList<>();for(int tp=1;tp<=3;tp++)for(int sl=1;sl<=3;sl++)matrix.add(new MatrixCell(tp,sl,outcomes.resolve(s,tp,sl).name(),0,0,0));Instant tpAt=s.tpHitAt(tpLevel),slAt=s.slHitAt(slLevel);String explanation=explain(selected,tpLevel,slLevel,tpAt,slAt);return new Detail(s.getId(),s.getCoin().getSymbol(),s.getCoin().getPair(),s.getSignalVersion(),s.getDirection().name(),s.getHorizonSeconds(),s.getOpenedAt(),s.getEntryPrice(),s.getRankingTpLevel(),s.getRankingTargetPercent(),s.getHistoricalSamples(),s.getHistoricalTargetHitRate(),s.getHistoricalDirectionalAccuracy(),s.getHistoricalWilsonScore(),s.getMixSize(),s.getMixRank(),s.getAgreementCount(),s.getTotalMethods(),s.getStrategyCodes(),s.getMethodNames(),s.getMinimumNotificationWinRatePercent(),s.isEligibleForNotification(),s.getNotificationSuppressionReason(),s.isTelegramSent(),s.getTelegramMessageId(),s.getNotificationDeliveryStatus().name(),s.getNotificationError(),tpLevel,slLevel,selected.name(),explanation,List.copyOf(timeline),matrix);
    }

    public byte[] csv(Filter filter) {
        Sql sql=sql(filter);MapSqlParameterSource params=copy(sql.params).addValue("limit",50000);String query="SELECT s.id,c.symbol,c.pair,s.direction,s.horizon_seconds,s.opened_at,s.entry_price,s.ranking_tp_level,s.ranking_target_percent,s.tp"+filter.tpLevel()+"_percent selected_tp_percent,s.sl"+filter.slLevel()+"_percent selected_sl_percent,s.tp"+filter.tpLevel()+"_hit_at selected_tp_at,s.sl"+filter.slLevel()+"_hit_at selected_sl_at,"+sql.outcome+" outcome,s.historical_target_hit_rate,s.historical_wilson_score,s.method_names,s.telegram_sent "+sql.fromWhere+" ORDER BY s.opened_at DESC,s.id DESC LIMIT :limit";StringBuilder out=new StringBuilder("ID,Coin,Pair,Direction,Horizon,Detected At,Entry,Ranking TP,Ranking Target %,Selected TP %,Selected SL %,TP Hit At,SL Hit At,First Touch Outcome,Historical Endpoint Hit Rate,Wilson,Methods,Telegram Sent\n");jdbc.query(query,params,rs->{out.append(rs.getLong("id")).append(',').append(csv(rs.getString("symbol"))).append(',').append(csv(rs.getString("pair"))).append(',').append(rs.getString("direction")).append(',').append(rs.getLong("horizon_seconds")).append(',').append(csv(String.valueOf(rs.getObject("opened_at")))).append(',').append(rs.getBigDecimal("entry_price")).append(',').append(rs.getInt("ranking_tp_level")).append(',').append(rs.getBigDecimal("ranking_target_percent")).append(',').append(rs.getBigDecimal("selected_tp_percent")).append(',').append(rs.getBigDecimal("selected_sl_percent")).append(',').append(csv(String.valueOf(rs.getObject("selected_tp_at")))).append(',').append(csv(String.valueOf(rs.getObject("selected_sl_at")))).append(',').append(rs.getString("outcome")).append(',').append(rs.getDouble("historical_target_hit_rate")).append(',').append(rs.getDouble("historical_wilson_score")).append(',').append(csv(rs.getString("method_names").replace("||"," + "))).append(',').append(rs.getBoolean("telegram_sent")).append('\n');});return out.toString().getBytes(StandardCharsets.UTF_8);
    }

    private List<Group> groupByDay(Sql sql){return jdbc.query("SELECT CAST(s.opened_at AS DATE) label,count(*) total,"+count("("+sql.outcome+"='SUCCESS')")+" successful,"+count("("+sql.outcome+"='FAILED')")+" failed,"+count("("+sql.outcome+"='UNRESOLVED')")+" unresolved "+sql.fromWhere+" GROUP BY CAST(s.opened_at AS DATE) ORDER BY label",sql.params,(r,n)->group(r));}
    private List<Group> groupByCoin(Sql sql){return jdbc.query("SELECT c.pair label,count(*) total,"+count("("+sql.outcome+"='SUCCESS')")+" successful,"+count("("+sql.outcome+"='FAILED')")+" failed,"+count("("+sql.outcome+"='UNRESOLVED')")+" unresolved "+sql.fromWhere+" GROUP BY c.pair ORDER BY count(*) DESC,c.pair",sql.params,(r,n)->group(r));}
    private List<Group> groupByHorizon(Sql sql){return jdbc.query("SELECT CAST(s.horizon_seconds AS VARCHAR) label,count(*) total,"+count("("+sql.outcome+"='SUCCESS')")+" successful,"+count("("+sql.outcome+"='FAILED')")+" failed,"+count("("+sql.outcome+"='UNRESOLVED')")+" unresolved "+sql.fromWhere+" GROUP BY s.horizon_seconds ORDER BY s.horizon_seconds",sql.params,(r,n)->group(r));}
    private List<MixGroup> groupByMix(Sql sql){return jdbc.query("SELECT c.pair,s.horizon_seconds,s.mix_rank,s.method_names,s.ranking_tp_level,avg(s.historical_target_hit_rate) historical_win_rate,avg(s.historical_wilson_score) wilson_score,count(*) total,"+count("("+sql.outcome+"='SUCCESS')")+" successful,"+count("("+sql.outcome+"='FAILED')")+" failed "+sql.fromWhere+" GROUP BY c.pair,s.horizon_seconds,s.mix_rank,s.method_names,s.ranking_tp_level ORDER BY count(*) DESC LIMIT 25",sql.params,(r,n)->{long a=r.getLong("successful"),b=r.getLong("failed");return new MixGroup(r.getString("pair"),r.getLong("horizon_seconds"),r.getInt("mix_rank"),r.getString("method_names").replace("||"," + "),r.getInt("ranking_tp_level"),r.getLong("total"),a,b,percent(a,a+b),r.getDouble("historical_win_rate"),r.getDouble("wilson_score"));});}
    private List<Bucket> buckets(Sql sql){String bucket="CASE WHEN s.historical_target_hit_rate<50 THEN '<50%' WHEN s.historical_target_hit_rate<55 THEN '50–55%' WHEN s.historical_target_hit_rate<60 THEN '55–60%' WHEN s.historical_target_hit_rate<65 THEN '60–65%' WHEN s.historical_target_hit_rate<70 THEN '65–70%' WHEN s.historical_target_hit_rate<75 THEN '70–75%' WHEN s.historical_target_hit_rate<80 THEN '75–80%' ELSE '80%+' END";return jdbc.query("SELECT "+bucket+" label,count(*) total,"+count("("+sql.outcome+"='SUCCESS')")+" successful,"+count("("+sql.outcome+"='FAILED')")+" failed "+sql.fromWhere+" GROUP BY "+bucket+" ORDER BY min(s.historical_target_hit_rate)",sql.params,(r,n)->{long a=r.getLong("successful"),b=r.getLong("failed");return new Bucket(r.getString("label"),r.getLong("total"),a+b,percent(a,a+b));});}
    private List<MatrixCell> matrix(Filter filter){Filter noOutcome=filter.withoutOutcome();Sql sql=sql(noOutcome);StringBuilder select=new StringBuilder("SELECT ");for(int tp=1;tp<=3;tp++)for(int sl=1;sl<=3;sl++){String o=outcome(tp,sl),prefix="t"+tp+"s"+sl;if(select.length()>7)select.append(',');select.append(count("("+o+"='SUCCESS')")).append(' ').append(prefix).append("_success,").append(count("("+o+"='FAILED')")).append(' ').append(prefix).append("_failed,").append(count("("+o+"='AMBIGUOUS')")).append(' ').append(prefix).append("_ambiguous");}Map<String,Object> row=jdbc.queryForMap(select+sql.fromWhere,sql.params);List<MatrixCell> cells=new ArrayList<>();for(int tp=1;tp<=3;tp++)for(int sl=1;sl<=3;sl++){String p="t"+tp+"s"+sl;long success=number(row,p+"_success"),failed=number(row,p+"_failed"),ambiguous=number(row,p+"_ambiguous");cells.add(new MatrixCell(tp,sl,null,success,failed,ambiguous));}return cells;}

    private Sql sql(Filter f){validateLevels(f.tpLevel(),f.slLevel());String outcome=outcome(f.tpLevel(),f.slLevel());StringBuilder where=new StringBuilder(" FROM mix_trade_simulations s JOIN coins c ON c.id=s.coin_id WHERE 1=1");MapSqlParameterSource p=new MapSqlParameterSource();add(where,p," AND UPPER(c.symbol)=UPPER(:coin)","coin",f.coin());add(where,p," AND UPPER(c.pair)=UPPER(:pair)","pair",f.pair());add(where,p," AND s.horizon_seconds=:horizon","horizon",f.horizon());add(where,p," AND s.direction=:direction","direction",f.direction());add(where,p," AND s.opened_at>=:fromAt","fromAt",f.from());add(where,p," AND s.opened_at<:toAt","toAt",f.to());add(where,p," AND s.historical_target_hit_rate>=:minimumWinRate","minimumWinRate",f.minimumHistoricalWinRate());add(where,p," AND s.historical_target_hit_rate<=:maximumWinRate","maximumWinRate",f.maximumHistoricalWinRate());add(where,p," AND s.mix_size=:mixSize","mixSize",f.mixSize());add(where,p," AND s.mix_rank=:mixRank","mixRank",f.mixRank());if(text(f.strategyCode())){where.append(" AND LOWER(s.strategy_codes) LIKE :strategyCode");p.addValue("strategyCode","%"+f.strategyCode().toLowerCase(Locale.ROOT)+"%");}if(text(f.method())){where.append(" AND LOWER(s.method_names) LIKE :method");p.addValue("method","%"+f.method().toLowerCase(Locale.ROOT)+"%");}add(where,p," AND s.eligible_for_notification=:eligible","eligible",f.notificationEligible());add(where,p," AND s.telegram_sent=:telegramSent","telegramSent",f.telegramSent());add(where,p," AND s.signal_version=:signalVersion","signalVersion",f.signalVersion());if(text(f.outcome())){String selected=f.outcome().equalsIgnoreCase("OPEN")?"UNRESOLVED":f.outcome().toUpperCase(Locale.ROOT);if(!Set.of("SUCCESS","FAILED","UNRESOLVED","AMBIGUOUS").contains(selected))throw new IllegalArgumentException("outcome must be SUCCESS, FAILED, UNRESOLVED, OPEN, or AMBIGUOUS");where.append(" AND ").append(outcome).append("=:outcome");p.addValue("outcome",selected);}return new Sql(where.toString(),outcome,p);}
    private String outcome(int tp,int sl){String t="s.tp"+tp+"_hit_at",l="s.sl"+sl+"_hit_at",ts="s.tp"+tp+"_hit_sequence",ls="s.sl"+sl+"_hit_sequence";return "CASE WHEN "+t+" IS NULL AND "+l+" IS NULL THEN 'UNRESOLVED' WHEN "+t+" IS NOT NULL AND "+l+" IS NULL THEN 'SUCCESS' WHEN "+t+" IS NULL THEN 'FAILED' WHEN "+t+"<"+l+" THEN 'SUCCESS' WHEN "+l+"<"+t+" THEN 'FAILED' WHEN "+ts+" IS NOT NULL AND "+ls+" IS NOT NULL AND "+ts+"<"+ls+" THEN 'SUCCESS' WHEN "+ts+" IS NOT NULL AND "+ls+" IS NOT NULL AND "+ls+"<"+ts+" THEN 'FAILED' ELSE 'AMBIGUOUS' END";}
    private String count(String condition){return "SUM(CASE WHEN "+condition+" THEN 1 ELSE 0 END)";}private void add(StringBuilder w,MapSqlParameterSource p,String sql,String name,Object value){if(value!=null&&(!(value instanceof String s)||text(s))){w.append(sql);p.addValue(name,value instanceof Enum<?>e?e.name():value);}}private boolean text(String s){return s!=null&&!s.isBlank();}private void validateLevels(int tp,int sl){if(tp<1||tp>3||sl<1||sl>3)throw new IllegalArgumentException("tpLevel and slLevel must be 1, 2, or 3");}private MapSqlParameterSource copy(MapSqlParameterSource source){MapSqlParameterSource copy=new MapSqlParameterSource();source.getValues().forEach(copy::addValue);return copy;}private long number(Map<String,Object>m,String key){Object n=m.get(key);return n==null?0:((Number)n).longValue();}private double decimal(Map<String,Object>m,String key){Object n=m.get(key);return n==null?0:((Number)n).doubleValue();}private double percent(long n,long d){return d==0?0:n*100.0/d;}private double rate(Map<String,Object>m,String key,long total){return percent(number(m,key),total);}private Group group(ResultSet r)throws SQLException{long a=r.getLong("successful"),b=r.getLong("failed");return new Group(r.getString("label"),r.getLong("total"),a,b,r.getLong("unresolved"),percent(a,a+b));}private Row row(ResultSet r)throws SQLException{Instant tp=instant(r,"selected_tp_at"),sl=instant(r,"selected_sl_at"),opened=instant(r,"opened_at");Instant first=tp==null?sl:sl==null?tp:tp.isBefore(sl)?tp:sl;return new Row(r.getLong("id"),r.getString("symbol"),r.getString("pair"),r.getString("direction"),r.getLong("horizon_seconds"),opened,r.getBigDecimal("entry_price"),r.getInt("mix_rank"),r.getInt("mix_size"),r.getString("method_names").replace("||"," + "),r.getDouble("historical_target_hit_rate"),r.getDouble("historical_wilson_score"),r.getInt("ranking_tp_level"),r.getBigDecimal("ranking_target_percent"),r.getBigDecimal("selected_tp_percent"),r.getBigDecimal("selected_sl_percent"),tp,sl,first,r.getString("outcome"),first==null?null:Duration.between(opened,first).toSeconds(),r.getBoolean("eligible_for_notification"),r.getBoolean("telegram_sent"),r.getString("notification_suppression_reason"),r.getString("status"));}private Instant instant(ResultSet r,String name)throws SQLException{var value=r.getTimestamp(name);return value==null?null:value.toInstant();}private String explain(FirstTouchOutcomeResolver.Outcome o,int tp,int sl,Instant t,Instant s){return switch(o){case SUCCESS->"TP"+tp+" was touched at "+t+(s==null?"; SL"+sl+" has not been touched.":" before SL"+sl+" at "+s+".");case FAILED->"SL"+sl+" was touched at "+s+(t==null?"; TP"+tp+" has not been touched.":" before TP"+tp+" at "+t+".");case AMBIGUOUS->"TP"+tp+" and SL"+sl+" were first observed at the same timestamp; true ordering is unavailable.";case UNRESOLVED->"Neither TP"+tp+" nor SL"+sl+" has been touched.";};}private String csv(String s){if(s==null)return "";return '"'+s.replace("\"","\"\"")+'"';}

    private record Sql(String fromWhere,String outcome,MapSqlParameterSource params){}
    public record Filter(String coin,String pair,Long horizon,String direction,Instant from,Instant to,int tpLevel,int slLevel,Double minimumHistoricalWinRate,Double maximumHistoricalWinRate,Integer mixSize,Integer mixRank,String strategyCode,String method,Boolean notificationEligible,Boolean telegramSent,String outcome,Integer signalVersion){public Filter withoutOutcome(){return new Filter(coin,pair,horizon,direction,from,to,tpLevel,slLevel,minimumHistoricalWinRate,maximumHistoricalWinRate,mixSize,mixRank,strategyCode,method,notificationEligible,telegramSent,null,signalVersion);}}
    public record Summary(long totalFoundSignals,long notificationEligible,long notificationSuppressed,long telegramSent,long openOrUnresolved,long resolved,long successful,long failed,long ambiguous,double successRate,double failureRate,double averageHistoricalWinRate,double averageDirectionalAccuracy,double averageWilsonScore,double averageAgreementRatio,double tp1ReachRate,double tp2ReachRate,double tp3ReachRate,double sl1ReachRate,double sl2ReachRate,double sl3ReachRate){}
    public record Group(String label,long total,long successful,long failed,long unresolved,double successRate){}
    public record MixGroup(String pair,long horizon,int mixRank,String methods,int rankingTpLevel,long found,long successful,long failed,double liveFirstTouchSuccessRate,double historicalEndpointHitRate,double wilsonScore){}
    public record Bucket(String label,long found,long resolved,double successRate){}
    public record MatrixCell(int tpLevel,int slLevel,String outcome,long successful,long failed,long ambiguous){@com.fasterxml.jackson.annotation.JsonProperty("successRate") public double successRate(){return successful+failed==0?0:successful*100.0/(successful+failed);}}
    public record Dashboard(Summary summary,List<Group>timeSeries,List<Group>coins,List<Group>horizons,List<MixGroup>mixes,List<Bucket>winRateBuckets,List<MatrixCell>matrix){}
    public record Row(long id,String coin,String pair,String direction,long horizon,Instant detectedAt,BigDecimal entryPrice,int mixRank,int mixSize,String methods,double historicalEndpointHitRate,double wilsonScore,int rankingTpLevel,BigDecimal rankingTargetPercent,BigDecimal selectedTpPercent,BigDecimal selectedSlPercent,Instant tpHitAt,Instant slHitAt,Instant firstTouchAt,String outcome,Long resolutionSeconds,boolean notificationEligible,boolean telegramSent,String suppressionReason,String simulationStatus){}
    public record Page(List<Row>content,int page,int size,long totalElements,int totalPages){}
    public record Milestone(String name,Instant at,Long sequence,BigDecimal price,BigDecimal percent){}
    public record Detail(long id,String coin,String pair,int signalVersion,String direction,long horizon,Instant detectedAt,BigDecimal entryPrice,int rankingTpLevel,BigDecimal rankingTargetPercent,long historicalSamples,double historicalEndpointHitRate,double directionalAccuracy,double wilsonScore,int mixSize,int mixRank,int agreement,int totalMethods,List<String>strategyCodes,List<String>methods,BigDecimal minimumNotificationWinRatePercent,boolean notificationEligible,String suppressionReason,boolean telegramSent,Long telegramMessageId,String notificationStatus,String notificationError,int selectedTpLevel,int selectedSlLevel,String selectedOutcome,String explanation,List<Milestone>timeline,List<MatrixCell>matrix){}
}
